using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // Preserve EF Core 8 id format ("Product|123") so existing 500K documents remain readable.
        // Without this, EF Core 9 generates ids as just the raw key value ("123").
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=PLACEHOLDER",
            "CatalogDb",
            cosmosOptions => { });
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // BREAKING CHANGE 1 — Discriminator property renamed from "Discriminator" to "$type".
        // Preserve the old property name so existing documents and direct SQL queries keep working.
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

        // BREAKING CHANGE 2 — Id format changed from "EntityType|Key" to raw key.
        // Preserve the "Product|{Id}" format so existing documents are still found.
        modelBuilder.Entity<Product>().HasPartitionKey(p => p.Id);
        modelBuilder.Entity<Product>().Property(p => p.Id)
            .HasConversion<string>();
        modelBuilder.Entity<Product>()
            .ToContainer("Products")
            .HasIdProperty("__id", IdPropertyConvention.EntityTypeAndKey);

        // BREAKING CHANGE 3 — HasIndex is not supported by the Cosmos provider (removed).
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

